namespace sv_02485741c9d5414bb25c0c784eab14da.Client.Models;

public sealed record StatusUpdate(DateTime Timestamp, string Status, string Location);

public sealed record Shipment(
    string TrackingNumber,
    string Status,
    string Location,
    DateTime EstimatedDelivery,
    IReadOnlyList<StatusUpdate> StatusUpdates);

using sv_02485741c9d5414bb25c0c784eab14da.Client.Models;

namespace sv_02485741c9d5414bb25c0c784eab14da.Client.Services;

public interface IShipmentService
{
    Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using sv_02485741c9d5414bb25c0c784eab14da.Client.Models;
using sv_02485741c9d5414bb25c0c784eab14da.Client.Services;

namespace sv_02485741c9d5414bb25c0c784eab14da.Services;

public sealed class ServerShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new Shipment(
            "PKG-001",
            "In Transit",
            "Chicago, IL",
            new DateTime(2026, 6, 20, 17, 0, 0, DateTimeKind.Utc),
            [
                new StatusUpdate(new DateTime(2026, 6, 14, 8, 0, 0, DateTimeKind.Utc), "Picked Up", "New York, NY"),
                new StatusUpdate(new DateTime(2026, 6, 15, 14, 30, 0, DateTimeKind.Utc), "In Transit", "Philadelphia, PA"),
                new StatusUpdate(new DateTime(2026, 6, 16, 9, 15, 0, DateTimeKind.Utc), "In Transit", "Chicago, IL"),
            ]),

        ["PKG-002"] = new Shipment(
            "PKG-002",
            "Delivered",
            "San Francisco, CA",
            new DateTime(2026, 6, 15, 12, 0, 0, DateTimeKind.Utc),
            [
                new StatusUpdate(new DateTime(2026, 6, 12, 10, 0, 0, DateTimeKind.Utc), "Picked Up", "Seattle, WA"),
                new StatusUpdate(new DateTime(2026, 6, 13, 6, 45, 0, DateTimeKind.Utc), "In Transit", "Portland, OR"),
                new StatusUpdate(new DateTime(2026, 6, 14, 11, 20, 0, DateTimeKind.Utc), "Out for Delivery", "San Francisco, CA"),
                new StatusUpdate(new DateTime(2026, 6, 14, 15, 5, 0, DateTimeKind.Utc), "Delivered", "San Francisco, CA"),
            ]),

        ["PKG-003"] = new Shipment(
            "PKG-003",
            "Processing",
            "Dallas, TX",
            new DateTime(2026, 6, 22, 18, 0, 0, DateTimeKind.Utc),
            [
                new StatusUpdate(new DateTime(2026, 6, 16, 7, 0, 0, DateTimeKind.Utc), "Label Created", "Dallas, TX"),
            ]),
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_02485741c9d5414bb25c0c784eab14da.Client.Models
@using sv_02485741c9d5414bb25c0c784eab14da.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

<h1>Shipment Tracking</h1>

@if (_isLoading)
{
    <div class="alert alert-info" role="status">
        <span class="spinner-border spinner-border-sm me-2" aria-hidden="true"></span>
        Loading shipment details for <strong>@TrackingNumber</strong>&hellip;
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p class="mb-2">@_errorMessage</p>
        <button class="btn btn-outline-danger btn-sm" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is not null)
{
    <div class="card mb-3">
        <div class="card-body">
            <h5 class="card-title">@_shipment.TrackingNumber</h5>
            <p><strong>Status:</strong> @_shipment.Status</p>
            <p><strong>Location:</strong> @_shipment.Location</p>
            <p><strong>Estimated Delivery:</strong> @_shipment.EstimatedDelivery.ToString("f")</p>
        </div>
    </div>

    <h4>Status History</h4>
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Time</th>
                <th>Status</th>
                <th>Location</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var update in _shipment.StatusUpdates)
            {
                <tr>
                    <td>@update.Timestamp.ToString("g")</td>
                    <td>@update.Status</td>
                    <td>@update.Location</td>
                </tr>
            }
        </tbody>
    </table>
}
else
{
    <div class="alert alert-warning" role="alert">
        No shipment found for tracking number <strong>@TrackingNumber</strong>.
    </div>
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = "";

    private CancellationTokenSource? _cts;
    private Shipment? _shipment;
    private bool _isLoading;
    private string? _errorMessage;

    protected override Task OnParametersSetAsync() => LoadShipmentAsync();

    private async Task LoadShipmentAsync()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        var cts = new CancellationTokenSource();
        _cts = cts;

        _shipment = null;
        _errorMessage = null;
        _isLoading = true;

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, cts.Token);
        }
        catch (OperationCanceledException) when (cts.Token.IsCancellationRequested)
        {
            // Superseded by a newer load or the component is disposing — exit silently.
            return;
        }
        catch (OperationCanceledException)
        {
            // Not our token — treat as a timeout.
            _errorMessage = "The request timed out. Please try again.";
            Logger.LogError("Timeout loading shipment {TrackingNumber}", TrackingNumber);
        }
        catch (TimeoutException)
        {
            _errorMessage = "The request timed out. Please try again.";
            Logger.LogError("Timeout loading shipment {TrackingNumber}", TrackingNumber);
        }
        catch (Exception ex)
        {
            _errorMessage = "Something went wrong loading shipment details. Please try again.";
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
        }
        finally
        {
            if (!cts.Token.IsCancellationRequested)
            {
                _isLoading = false;
            }
        }
    }

    private Task RetryAsync() => LoadShipmentAsync();

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

