+@page "/shipments/{TrackingNumber}"
+@rendermode InteractiveAuto
+@using sv_02485741c9d5414bb25c0c784eab14da.Client.Models
+@using sv_02485741c9d5414bb25c0c784eab14da.Client.Services
+@inject IShipmentService ShipmentService
+@inject ILogger<ShipmentTracker> Logger
+@implements IDisposable
+
+<PageTitle>Shipment @TrackingNumber</PageTitle>
+
+<h1>Shipment Tracking</h1>
+
+@if (_isLoading)
+{
+    <div class="alert alert-info" role="status">
+        <span class="spinner-border spinner-border-sm me-2" aria-hidden="true"></span>
+        Loading shipment details for <strong>@TrackingNumber</strong>&hellip;
+    </div>
+}
+else if (_errorMessage is not null)
+{
+    <div class="alert alert-danger" role="alert">
+        <p class="mb-2">@_errorMessage</p>
+        <button class="btn btn-outline-danger btn-sm" @onclick="RetryAsync">Retry</button>
+    </div>
+}
+else if (_shipment is not null)
+{
+    <div class="card mb-3">
+        <div class="card-body">
+            <h5 class="card-title">@_shipment.TrackingNumber</h5>
+            <p><strong>Status:</strong> @_shipment.Status</p>
+            <p><strong>Location:</strong> @_shipment.Location</p>
+            <p><strong>Estimated Delivery:</strong> @_shipment.EstimatedDelivery.ToString("f")</p>
+        </div>
+    </div>
+
+    <h4>Status History</h4>
+    <table class="table table-striped">
+        <thead>
+            <tr>
+                <th>Time</th>
+                <th>Status</th>
+                <th>Location</th>
+            </tr>
+        </thead>
+        <tbody>
+            @foreach (var update in _shipment.StatusUpdates)
+            {
+                <tr>
+                    <td>@update.Timestamp.ToString("g")</td>
+                    <td>@update.Status</td>
+                    <td>@update.Location</td>
+                </tr>
+            }
+        </tbody>
+    </table>
+}
+else
+{
+    <div class="alert alert-warning" role="alert">
+        No shipment found for tracking number <strong>@TrackingNumber</strong>.
+    </div>
+}
+
+@code {
+    [Parameter]
+    public string TrackingNumber { get; set; } = "";
+
+    private CancellationTokenSource? _cts;
+    private Shipment? _shipment;
+    private bool _isLoading;
+    private string? _errorMessage;
+
+    protected override Task OnParametersSetAsync() => LoadShipmentAsync();
+
+    private async Task LoadShipmentAsync()
+    {
+        _cts?.Cancel();
+        _cts?.Dispose();
+        var cts = new CancellationTokenSource();
+        _cts = cts;
+
+        _shipment = null;
+        _errorMessage = null;
+        _isLoading = true;
+
+        try
+        {
+            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, cts.Token);
+        }
+        catch (OperationCanceledException) when (cts.Token.IsCancellationRequested)
+        {
+            // Superseded by a newer load or the component is disposing — exit silently.
+            return;
+        }
+        catch (OperationCanceledException)
+        {
+            // Not our token — treat as a timeout.
+            _errorMessage = "The request timed out. Please try again.";
+            Logger.LogError("Timeout loading shipment {TrackingNumber}", TrackingNumber);
+        }
+        catch (TimeoutException)
+        {
+            _errorMessage = "The request timed out. Please try again.";
+            Logger.LogError("Timeout loading shipment {TrackingNumber}", TrackingNumber);
+        }
+        catch (Exception ex)
+        {
+            _errorMessage = "Something went wrong loading shipment details. Please try again.";
+            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
+        }
+        finally
+        {
+            if (!cts.Token.IsCancellationRequested)
+            {
+                _isLoading = false;
+            }
+        }
+    }
+
+    private Task RetryAsync() => LoadShipmentAsync();
+
+    public void Dispose()
+    {
+        _cts?.Cancel();
+        _cts?.Dispose();
+    }
+}
